(7387367, 1159100, 73942, '<td valign="top">very cool</td>', 'very cool', '2015-07-15 10:57:46.000000', NULL, 1),
(7387579, 1159302, 37858, '<td valign="top">I would have preferred that this image was larger, to better see and evaluate it.  It looks interesting, but is difficult to make out with my tired old eyes.  I''m wondering if this is a photo of an old slide, given the frame dimensions. 6 (might have been higher if larger)</td>', 'I would have preferred that this image was larger, to better see and evaluate it.  It looks interesting, but is difficult to make out with my tired old eyes.  I''m wondering if this is a photo of an old slide, given the frame dimensions. 6 (might have been higher if larger)', '2015-07-15 15:13:51.000000', NULL, 1),
(7387581, 1159659, 37858, '<td valign="top">Interesting shot.  I can''t tell whether this was a shot of a pool of water or whether you were using art filters.  Hope you have some explanation with this.  I''d also like to see this in color.  In my mind''s eye that would be very colorful, saturated, and artistic.</td>', 'Interesting shot.  I can''t tell whether this was a shot of a pool of water or whether you were using art filters.  Hope you have some explanation with this.  I''d also like to see this in color.  In my mind''s eye that would be very colorful, saturated, and artistic.', '2015-07-15 15:17:06.000000', NULL, 1),
(7387584, 1159183, 37858, '<td valign="top">My favorite image.  Love the tones and muted colors.  Very painterly treatment.  I''ve reserved the Blue Ribbon for you.  Now let''s see if the other voters agree.</td>', 'My favorite image.  Love the tones and muted colors.  Very painterly treatment.  I''ve reserved the Blue Ribbon for you.  Now let''s see if the other voters agree.', '2015-07-15 15:19:11.000000', NULL, 1),
(7387586, 1159632, 37858, '<td valign="top">One of my ribbon choices.  Love the lighting and processing.</td>', 'One of my ribbon choices.  Love the lighting and processing.', '2015-07-15 15:22:37.000000', NULL, 1),
(7387588, 1159638, 37858, '<td valign="top">I like this photo a lot because of the colors, lighting, and composition.  Not a fan of the border, though.</td>', 'I like this photo a lot because of the colors, lighting, and composition.  Not a fan of the border, though.', '2015-07-15 15:24:10.000000', NULL, 1),
(7387590, 1159534, 37858, '<td valign="top">One of my choices to ribbon.  Nails the challenge topic.  I also like the composition, with the labels on the left.</td>', 'One of my choices to ribbon.  Nails the challenge topic.  I also like the composition, with the labels on the left.', '2015-07-15 15:25:41.000000', NULL, 1),
(7387868, 1159125, 135744, '<td valign="top">Beautiful fields of Lavender.</td>', 'Beautiful fields of Lavender.', '2015-07-16 09:47:26.000000', NULL, 1),
(7387873, 1159517, 135744, '<td valign="top">One of my top picks. Simple but very effective.</td>', 'One of my top picks. Simple but very effective.', '2015-07-16 09:54:34.000000', NULL, 1),
(7387875, 1159639, 135744, '<td valign="top">Very nice indeed. Hope it does well for you.</td>', 'Very nice indeed. Hope it does well for you.', '2015-07-16 09:55:00.000000', NULL, 1),
(7387878, 1159183, 135744, '<td valign="top">A masterpiece guaranteed to take the blue with flying colours. I can safely say congrats now as nothing comes even close to this.</td>', 'A masterpiece guaranteed to take the blue with flying colours. I can safely say congrats now as nothing comes even close to this.', '2015-07-16 09:55:57.000000', NULL, 1),
(7387989, 1159525, 173844, '<td valign="top">Fine image, as if a drop of water is being grasped.  Fertile depth of field.  I like the prominence the clouds in the glass ball attain, implying that herein is the reality, if you pay attention.  One of my favorites.</td>', 'Fine image, as if a drop of water is being grasped.  Fertile depth of field.  I like the prominence the clouds in the glass ball attain, implying that herein is the reality, if you pay attention.  One of my favorites.', '2015-07-16 13:50:56.000000', NULL, 1),
(7387994, 1159183, 173844, '<td valign="top">Humbly dramatic.  Reminds me of a dark Japanese movie, a solemn drumbeat and throaty flute marking unfathomable emotion. The blown fabric mesmerizing and alive.  One of my favorites.</td>', 'Humbly dramatic.  Reminds me of a dark Japanese movie, a solemn drumbeat and throaty flute marking unfathomable emotion. The blown fabric mesmerizing and alive.  One of my favorites.', '2015-07-16 13:55:48.000000', NULL, 1),
(7387996, 1159526, 173844, '<td valign="top">Simple - at first glance - and beautiful.  The delicate composition is thrilling.  The blues are a wonderful counterpoint to the greens, bringing down the sky as a benediction.  Personal favorite.</td>', 'Simple - at first glance - and beautiful.  The delicate composition is thrilling.  The blues are a wonderful counterpoint to the greens, bringing down the sky as a benediction.  Personal favorite.', '2015-07-16 14:01:17.000000', NULL, 1),
(7388058, 1159659, 173844, '<td valign="top">Apt transparency through which to view this rainy day.  Black and white is a noteworthy choice, highlighting masses and tones.  A graphically modern sensibility.</td>', 'Apt transparency through which to view this rainy day.  Black and white is a noteworthy choice, highlighting masses and tones.  A graphically modern sensibility.', '2015-07-16 16:53:10.000000', NULL, 1),
(7388063, 1159642, 173844, '<td valign="top">Handsome/pretty lab looking appealingly out through the screen, the caught rain adding both poignancy and atmosphere.  The colors are gently harmonious.  An additional aspect of photographing through the screen is the simulation of a heavily woven canvas.</td>', 'Handsome/pretty lab looking appealingly out through the screen, the caught rain adding both poignancy and atmosphere.  The colors are gently harmonious.  An additional aspect of photographing through the screen is the simulation of a heavily woven canvas.', '2015-07-16 17:03:43.000000', NULL, 1),
(7388064, 1159535, 173844, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2015-07-16 17:04:39.000000', NULL, 1),
(7388066, 1159106, 173844, '<td valign="top">Is the transparency here the camera lens?  In any case, I like the bold choice of placing the seeming subjects at the peripheries.  Mysterious overall, enhanced by the glow, if I may call it that.</td>', 'Is the transparency here the camera lens?  In any case, I like the bold choice of placing the seeming subjects at the peripheries.  Mysterious overall, enhanced by the glow, if I may call it that.', '2015-07-16 17:11:46.000000', NULL, 1),
(7388067, 1159557, 173844, '<td valign="top">I''m stumped but intrigued, an interesting sensation.  Whatever it is, I like it.</td>', 'I''m stumped but intrigued, an interesting sensation.  Whatever it is, I like it.', '2015-07-16 17:13:45.000000', NULL, 1),
(7388071, 1159648, 173844, '<td valign="top">Provocative assemblage here, and it grabs my amused attention, though I''m at a loss a to what now?  That''s probably superfluous.  Surreal for it''s own sake.  I like how the smiley face eyes seem to be looking upwards and that the cat seems to be sporting priestly garb.  Suavely handled.</td>', 'Provocative assemblage here, and it grabs my amused attention, though I''m at a loss a to what now?  That''s probably superfluous.  Surreal for it''s own sake.  I like how the smiley face eyes seem to be looking upwards and that the cat seems to be sporting priestly garb.  Suavely handled.', '2015-07-16 17:20:59.000000', NULL, 1),
(7388073, 1159652, 173844, '<td valign="top">Fascinating glimpse of an overlapping moment.</td>', 'Fascinating glimpse of an overlapping moment.', '2015-07-16 17:22:51.000000', NULL, 1),
(7388075, 1159504, 173844, '<td valign="top">Nice idea, well carried out.  Is that you, Yorick?</td>', 'Nice idea, well carried out.  Is that you, Yorick?', '2015-07-16 17:24:28.000000', NULL, 1),
(7388077, 1159534, 173844, '<td valign="top">A warm, interesting image, subtly softened through the glass.  In my humble opinion, the signage is a distraction.</td>', 'A warm, interesting image, subtly softened through the glass.  In my humble opinion, the signage is a distraction.', '2015-07-16 17:26:39.000000', NULL, 1),
(7388078, 1159597, 173844, '<td valign="top">A comfortable, calm image and composition.  Just what a fog should be.</td>', 'A comfortable, calm image and composition.  Just what a fog should be.', '2015-07-16 17:27:48.000000', NULL, 1),
